effect.shader:
const int MAX_SAMPLES = 64;

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float rad = radians(angle);
    vec2 axis = vec2(cos(rad), sin(rad)) * acTexelSize * reach * acEscalaDePixel;
    int samples = clamp(int(quality + 0.5), 1, MAX_SAMPLES);

    vec3 streak = vec3(0.0);
    float weightSum = 0.0;

    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (i >= samples) break;
        // Vai dos dois lados a partir do pixel: o risco é simétrico.
        float t = (float(i) / float(samples - 1)) * 2.0 - 1.0;
        vec4 texel = texture(inputImg, clamp(acScreenNorm + axis * t, 0.0, 1.0));

        float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114)) * texel.a;
        float bright = smoothstep(threshold, min(threshold + 0.2, 1.0), luma);

        // Peso caindo com a distância: sem isso o risco tem a mesma força na
        // ponta e no meio, e parece uma barra em vez de um brilho.
        float weight = 1.0 - abs(t);
        streak += texel.rgb * bright * weight;
        weightSum += weight;
    }

    streak *= intensity / max(weightSum, 0.0001);

    // Somado: luz se acumula. Misturar deixaria a imagem lavada.
    vec3 result = original.rgb + streak * streakColor.rgb * streakColor.a;
    fragColor = vec4(clamp(result, 0.0, 1.0), original.a);
}
